/* =====================================================================
   00_rom.sql -- ZX Spectrum 48K ROM image, CRC32 0xDDEE531F.

   Amstrad permit redistribution of the Sinclair ROMs for emulation, so
   this can live in source control. Run AFTER 01_schema and 03_driver.

   The image is appended in 2000-byte chunks: a T-SQL binary literal
   cannot contain whitespace, so it must not be wrapped across lines.
   ===================================================================== */
SET NOCOUNT ON;
GO

DECLARE @rom varbinary(max);
SET @rom = ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
SET @rom = @rom + ;
DECLARE @rom_len int = DATALENGTH(@rom);
IF @rom_len <> 16384
BEGIN
    RAISERROR('@rom is %d bytes, expected 16384', 16, 1, @rom_len);
END

EXEC dbo.z80_load_bin @data = @rom, @addr = 0, @allow_rom = 1;

DECLARE @check bigint;
SELECT @check = SUM(CAST(val AS bigint)) FROM dbo.z80_mem WHERE addr < 16384;
IF @check = 1926175
BEGIN
    PRINT 'ROM loaded and verified (byte sum 1926175)';
END
ELSE
BEGIN
    RAISERROR('ROM byte sum is %I64d, expected 1926175', 16, 1, @check);
END
GO
